import Foundation

// MARK: - Lesson content (hand-written in course.json, or generated by AI)

struct Lesson: Decodable, Identifiable {
    let id: String
    let title: String
    let subtitle: String
    let icon: String
    let tips: [Tip]
    let items: [Item]
    let exercises: [AuthoredExercise]
}

struct Tip: Codable, Hashable {
    let title: String
    let body: String
}

struct Item: Codable, Identifiable, Hashable {
    let id: String
    let es: String
    let zh: String
    let note: String?
    let pron: String?
    let tts: String?

    /// Text handed to the speech synthesizer (e.g. "chino, china" for "chino / china").
    var speakText: String { tts ?? es }

    /// Number of words in the Spanish text (used to pick sentence-level drills).
    var wordCount: Int { es.split(whereSeparator: { $0.isWhitespace }).count }

    /// True for "x / y" style entries that are not real sentences.
    var isPair: Bool { es.contains(" / ") }
}

// MARK: - Hand-written exercises

enum AuthoredExercise: Decodable {
    case build(BuildExercise)
    case fill(FillExercise)
    case type(TypeExercise)
    case choice(ChoiceExercise)

    private enum CodingKeys: String, CodingKey { case type }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let kind = try container.decode(String.self, forKey: .type)
        switch kind {
        case "build": self = .build(try BuildExercise(from: decoder))
        case "fill": self = .fill(try FillExercise(from: decoder))
        case "type": self = .type(try TypeExercise(from: decoder))
        case "choice": self = .choice(try ChoiceExercise(from: decoder))
        default:
            throw DecodingError.dataCorruptedError(
                forKey: .type, in: container,
                debugDescription: "Unknown exercise type \(kind)")
        }
    }
}

/// Put the words in the right order.
struct BuildExercise: Decodable {
    let prompt: String
    let answer: [String]
    let distractors: [String]?
    let full: String
}

/// Sentence with a blank (___) and a few options.
struct FillExercise: Decodable {
    let sentence: String
    let zh: String
    let options: [String]
    let answer: String
    let explain: String?
}

/// Translate the Chinese prompt by typing Spanish (or, with `audio`, a dictation).
struct TypeExercise: Decodable {
    let prompt: String
    let answers: [String]
    let display: String?
    let hint: String?
    var audio: String? = nil

    var displayAnswer: String { display ?? answers.first ?? "" }
}

/// Free-form multiple-choice question.
struct ChoiceExercise: Decodable {
    let question: String
    let sub: String?
    let options: [String]
    let answer: Int
    let explain: String?
    let spanishOptions: Bool?
}

// MARK: - Reference pages

struct RefPage: Decodable, Identifiable {
    let id: String
    let title: String
    let subtitle: String
    let icon: String
    let sections: [RefSection]
}

struct RefSection: Decodable {
    let heading: String
    let body: String?
    let table: RefTable?
}

struct RefTable: Decodable {
    let columns: [String]
    let rows: [[String]]
    /// Column indexes that hold Spanish text (tap to hear).
    let speak: [Int]?
}

// MARK: - Files on disk

/// course.json — the hand-written A1 course and reference pages.
struct CourseFile: Decodable {
    let version: Int
    let units: [CourseUnit]
    let reference: [RefPage]
}

struct CourseUnit: Decodable {
    let id: String
    let title: String
    let subtitle: String
    let color: String
    let lessons: [Lesson]
}

/// syllabus.json — level descriptions and the A2–C2 lesson plan (generated by AI on demand).
struct SyllabusFile: Decodable {
    let levels: [SyllabusLevel]
}

struct SyllabusLevel: Decodable {
    let id: String
    let title: String
    let subtitle: String
    let summary: String
    let color: String
    let units: [SyllabusUnit]
}

struct SyllabusUnit: Decodable {
    let id: String
    let title: String
    let subtitle: String
    let lessons: [LessonSpec]
}

/// What an AI-generated lesson must cover.
struct LessonSpec: Codable {
    let id: String
    let title: String
    let subtitle: String
    let icon: String
    let grammar: [String]
    let vocab: String
    let functions: [String]?
    let culture: String?
}

// MARK: - Runtime structure

struct LessonEntry: Identifiable {
    let id: String
    let title: String
    let subtitle: String
    let icon: String
    let levelId: String
    let unitTitle: String
    let color: String
    /// Hand-written content, if any.
    let bundled: Lesson?
    /// Plan for AI generation, if not hand-written.
    let spec: LessonSpec?

    var isAI: Bool { bundled == nil }
}

struct UnitEntry: Identifiable {
    let id: String
    let title: String
    let subtitle: String
    let color: String
    let lessons: [LessonEntry]
}

struct LevelEntry: Identifiable {
    let id: String
    let title: String
    let subtitle: String
    let summary: String
    let color: String
    let units: [UnitEntry]

    var lessons: [LessonEntry] { units.flatMap { $0.lessons } }
}

// MARK: - Item lookup across bundled, generated and saved items

final class ItemIndex {
    static let shared = ItemIndex()
    private var items: [String: Item] = [:]
    private let lock = NSLock()

    func register(_ list: [Item]) {
        lock.lock(); defer { lock.unlock() }
        for item in list { items[item.id] = item }
    }

    func item(_ id: String) -> Item? {
        lock.lock(); defer { lock.unlock() }
        return items[id]
    }
}

// MARK: - Loading

final class CourseStore {
    static let shared = CourseStore()

    let levels: [LevelEntry]
    let reference: [RefPage]
    let loadError: String?
    let lessonsInOrder: [LessonEntry]
    private let entriesById: [String: LessonEntry]
    private let levelIndexById: [String: Int]

    private init() {
        var failure: String?
        var courseFile: CourseFile?
        var syllabusFile: SyllabusFile?

        func load<T: Decodable>(_ name: String, as type: T.Type) -> T? {
            guard let url = Bundle.main.url(forResource: name, withExtension: "json") else {
                failure = "找不到 \(name).json"
                return nil
            }
            do {
                return try JSONDecoder().decode(T.self, from: Data(contentsOf: url))
            } catch {
                failure = "\(name).json 读取失败：\(error)"
                return nil
            }
        }
        courseFile = load("course", as: CourseFile.self)
        syllabusFile = load("syllabus", as: SyllabusFile.self)

        var built: [LevelEntry] = []
        for level in syllabusFile?.levels ?? [] {
            var units: [UnitEntry] = []
            if level.id == "A1" {
                for unit in courseFile?.units ?? [] {
                    let lessons = unit.lessons.map {
                        LessonEntry(id: $0.id, title: $0.title, subtitle: $0.subtitle, icon: $0.icon,
                                    levelId: level.id, unitTitle: unit.title, color: unit.color,
                                    bundled: $0, spec: nil)
                    }
                    units.append(UnitEntry(id: unit.id, title: unit.title, subtitle: unit.subtitle,
                                           color: unit.color, lessons: lessons))
                }
            }
            for unit in level.units {
                let lessons = unit.lessons.map {
                    LessonEntry(id: $0.id, title: $0.title, subtitle: $0.subtitle, icon: $0.icon,
                                levelId: level.id, unitTitle: unit.title, color: level.color,
                                bundled: nil, spec: $0)
                }
                units.append(UnitEntry(id: unit.id, title: unit.title, subtitle: unit.subtitle,
                                       color: level.color, lessons: lessons))
            }
            built.append(LevelEntry(id: level.id, title: level.title, subtitle: level.subtitle,
                                    summary: level.summary, color: level.color, units: units))
        }

        levels = built
        reference = courseFile?.reference ?? []
        loadError = failure
        lessonsInOrder = built.flatMap { $0.lessons }

        var byId: [String: LessonEntry] = [:]
        for entry in lessonsInOrder { byId[entry.id] = entry }
        entriesById = byId

        var levelIdx: [String: Int] = [:]
        for (i, level) in built.enumerated() { levelIdx[level.id] = i }
        levelIndexById = levelIdx

        ItemIndex.shared.register(lessonsInOrder.compactMap { $0.bundled }.flatMap { $0.items })
    }

    func entry(_ id: String) -> LessonEntry? { entriesById[id] }

    func item(_ id: String) -> Item? { ItemIndex.shared.item(id) }

    func levelIndex(_ levelId: String) -> Int { levelIndexById[levelId] ?? 0 }

    func level(_ id: String) -> LevelEntry? { levels.first { $0.id == id } }

    /// Items from the other lessons in the same unit (used for distractors).
    func unitItems(for lessonId: String) -> [Item] {
        for level in levels {
            for unit in level.units where unit.lessons.contains(where: { $0.id == lessonId }) {
                return unit.lessons.compactMap { LessonRepository.shared.lesson(for: $0) }.flatMap { $0.items }
            }
        }
        return []
    }
}
